// Helper functions
export function getBusinessesByCategory(category: string): Business[] {
  return businesses.filter((b) => b.category === category);
}

export function getBusinessesByNeighborhood(neighborhood: string): Business[] {
  return businesses.filter((b) => b.neighborhoods.includes(neighborhood));
}

export function getBusinessesByCategoryAndNeighborhood(category: string, neighborhood: string): Business[] {
  return businesses.filter((b) => b.category === category && b.neighborhoods.includes(neighborhood));
}

export function getBusinessById(id: string): Business | undefined {
  return businesses.find((b) => b.id === id);
}